type Screen = "splash" | "register" | "login" | "forgot" | "reset" | "home" | "chat" | "wellness" | "cycle" | "shop" | "donation" | "nutrition" | "nutrition-dashboard" | "community-hub" | "profile-settings";
type IconName = "bell" | "brain" | "chevron" | "back" | "community" | "heart" | "home" | "language" | "logout" | "menu" | "mic" | "nutrition" | "profile" | "search" | "send" | "settings" | "sparkle" | "x" | "cart" | "upload" | "download" | "camera" | "eye" | "eyeOff";
const iconMap: Record<IconName, LucideIcon> = { bell: Bell, brain: Brain, chevron: ChevronRight, back: ChevronLeft, community: Users, heart: HeartPulse, home: HomeIcon, language: Languages, logout: LogOut, menu: Menu, mic: Mic, nutrition: Apple, profile: UserRound, search: Search, send: Send, settings: Settings, sparkle: Sparkles, x: X, cart: ShoppingBag, upload: Upload, download: Download, camera: Camera, eye: Eye, eyeOff: EyeOff };
function Icon({ name, size = 21 }: { name: IconName; size?: number }) { return createElement(iconMap[name], { "aria-hidden": true, className: "icon", size, strokeWidth: 1.8 }); }

function Logo({ light = false }: { light?: boolean }) {
  return <div className={`logo ${light ? "logo--light" : ""}`}><span className="logo-mark"><Icon name="heart" size={22}/><b>+</b></span><span>ImpiloHealth<span>-AI</span></span></div>;
}

function HuaweiMark({ light = false }: { light?: boolean }) {
  return <div className={`huawei ${light ? "huawei--light" : ""}`} aria-label="Huawei Technologies"><span className="huawei-flower"><Sparkles size={24}/></span><span><b>HUAWEI</b><small>TECHNOLOGIES</small></span></div>;
}

