  Sotho: { getStarted:"Qala", tagline:"Bophelo ba Hao. Setjhaba sa Hao. E tsamaiswa ke AI.", welcome:"Tlhokomelo ya setjhaba ka AI", login:"Kena", register:"Ngodisa", dashboard:"Lehae", health:"Puisano ya Bophelo", mood:"Maikutlo le Bophelo", women:"Bophelo ba Basadi", shop:"Lebenkele la Tlhokomelo", nutrition:"Phepo e Bohlale", scanner:"Sekena sa Dijo", community:"Setjhaba", donate:"Nehela", profile:"Profaele", greeting:"Dumela, Jennifer", body:"Mmele wa hao o ikutlwa jwang kajeno?", hub:"Setsi sa hao sa bophelo" },
