function Wellness() {
  const moods = [{e:"😢",l:"Awful"},{e:"😔",l:"Low"},{e:"😕",l:"Off"},{e:"😐",l:"Okay"},{e:"🙂",l:"Good"},{e:"😊",l:"Great"},{e:"🤩",l:"Amazing"}]; const [mood, setMood] = useState("🙂"); const [modal, setModal] = useState(false); const [toast,setToast]=useState("");
  return <><HeaderBand eyebrow="WELLNESS OVERVIEW" title="How have you been feeling?" text="Notice your patterns, celebrate progress, and take a moment for yourself."><span className="learning-badge"><i/> AI is learning your patterns</span></HeaderBand><div className="wellness-layout"><section className="chart-card"><div className="card-heading"><div><span>WEEKLY MOOD</span><h3>Your emotional rhythm</h3></div><select aria-label="Chart period"><option>This week</option><option>Last week</option></select></div><MoodChart/><div className="chart-legend"><span><i/> Your mood</span><b>Average: Good 🙂</b></div></section><section className="checkin"><span>TODAY'S CHECK-IN</span><h3>How do you feel right now?</h3><p>Select the mood that feels closest.</p><div className="mood-options">{moods.map((item) => <button className={mood === item.e ? "active" : ""} onClick={() => {setMood(item.e);setToast(`Check-in saved — ${item.e}`);setTimeout(()=>setToast(""),1800)}} key={item.l}><span>{item.e}</span><small>{item.l}</small></button>)}</div><button className="button button--gradient save-mood">Save today’s mood</button></section><article className="wellness-insight"><span className="insight-icon"><Icon name="sparkle"/></span><div><small>YOUR AI INSIGHT</small><h3>AI noticed you’ve seemed stressed this week</h3><p>Your check-ins suggest more tension than usual. A short pause may help your body reset.</p><div className="insight-meta"><span>Most common mood: <b>Okay 😐</b></span><span>Pattern confidence: <b>High</b></span></div></div></article><article className="breathing-card"><div className="breathing-visual"><i/><span>Breathe</span></div><div><small>SUGGESTED FOR YOU</small><h3>5-min breathing exercise</h3><p>A guided moment to slow down, release tension, and feel grounded.</p><button className="button button--gradient" onClick={() => setModal(true)}>Begin exercise <Icon name="chevron" size={17}/></button></div></article></div>{toast&&<div className="toast"><Check size={17}/><span>{toast}<small>Your AI is learning your patterns</small></span></div>}<p className="medical-note">AI wellness insights are supportive guidance and are not a substitute for professional medical advice.</p>{modal && <div className="modal-backdrop" role="presentation" onMouseDown={() => setModal(false)}><section className="breathing-modal" role="dialog" aria-modal="true" aria-label="Breathing exercise" onMouseDown={(e) => e.stopPropagation()}><button className="icon-button modal-close" onClick={() => setModal(false)} aria-label="Close"><Icon name="x"/></button><span className="modal-kicker">5-MINUTE RESET</span><h2>Let’s breathe together</h2><p>Follow the circle. Breathe in as it expands, and breathe out as it softens.</p><div className="breath-orb"><div><b>Breathe in</b><small>4 seconds</small></div></div><span className="breath-count">1 of 8 breaths</span><button className="text-button" onClick={() => setModal(false)}>End exercise</button></section></div>}</>;
}


function FloatingAI() { return <div className="floating-ai" title="Huawei AI active"><span><Icon name="sparkle" size={17}/></span><div><b>Huawei AI</b><small>Concept demo</small></div></div>; }

const monthDays = Array.from({ length: 35 }, (_, index) => index - 2);
function Cycle({ navigate }: { navigate: (screen: Screen) => void }) {
  const [symptoms, setSymptoms] = useState(["Cramps"]); const [flow, setFlow] = useState("Medium"); const [toast,setToast]=useState(false);
  const [pred,setPred]=useState<Prediction|null>(null); const [predErr,setPredErr]=useState("");
  useEffect(()=>{api.prediction().then(setPred).catch(e=>setPredErr(e instanceof ApiError?e.message:"Could not load prediction"))},[]);
  const toggle = (item: string) => setSymptoms((all) => all.includes(item) ? all.filter((x) => x !== item) : [...all, item]);
  return <><HeaderBand eyebrow="WOMEN'S HEALTH" title="Period Tracker" text="Understand your cycle with private, AI-supported predictions."><button className="button button--glass" onClick={() => navigate("shop")}>Visit the Period Care Shop <Icon name="chevron" size={17}/></button></HeaderBand><section className="panel" aria-live="polite" style={{marginBottom:16,padding:20}}><span className="card-label">LIVE PREDICTION · FROM YOUR BACKEND</span>{predErr?<p>{predErr}</p>:!pred?<p>Loading…</p>:!pred.available?<p>Not enough data yet. Log at least two periods to get a prediction ({pred.cyclesUsed} cycles used).</p>:<p>Next period: <b>{pred.nextPeriodStart}</b> (in {pred.daysUntilNextPeriod} days) · Fertile window: <b>{pred.fertileWindowStart}</b> to <b>{pred.fertileWindowEnd}</b> · Average cycle {pred.averageCycleLength} days · based on {pred.cyclesUsed} cycles</p>}</section><div className="cycle-layout"><section className="cycle-calendar panel"><div className="calendar-title"><button aria-label="Previous month"><Icon name="back"/></button><div><small>MAY</small><h3>May 2025</h3></div><button aria-label="Next month"><Icon name="chevron"/></button></div><div className="weekdays">{["S","M","T","W","T","F","S"].map((day,i)=><span key={`${day}${i}`}>{day}</span>)}</div><div className="calendar-days">{monthDays.map((day,i)=><button className={day>0&&day<6?"cycle-day":day>14&&day<20?"fertile-day":""} key={i} disabled={day<1||day>31}>{day>0&&day<=31?day:""}</button>)}</div><div className="calendar-key"><span><i className="period-key"/>Period</span><span><i className="fertile-key"/>Fertile window</span><span><i className="today-key"/>Today</span></div></section><aside className="cycle-side"><article className="next-period panel"><span className="module-icon pink"><Icon name="heart"/></span><div><small>NEXT PERIOD</small><h3>In 12 days</h3><p>Expected 7 June • 5 days</p></div></article><section className="cycle-log panel"><span className="card-label">QUICK LOG</span><h3>How are you feeling?</h3><p>Symptoms</p><div className="symptom-chips">{["Cramps","Bloating","Headache","Mood swings","Fatigue","Cravings"].map((item)=><button className={symptoms.includes(item)?"active":""} onClick={()=>toggle(item)} key={item}>{item}</button>)}</div><p>Flow intensity</p><div className="flow-options">{["Light","Medium","Heavy"].map((item)=><button className={flow===item?"active":""} onClick={()=>setFlow(item)} key={item}><span>{"●".repeat(item==="Light"?1:item==="Medium"?2:3)}</span>{item}</button>)}</div><button className="button button--gradient quick-log" onClick={()=>{setToast(true);setTimeout(()=>setToast(false),1800)}}>Quick log</button></section><div className="prediction-badge"><Icon name="sparkle"/><span><b>AI Cycle Prediction</b><small>Powered by Pangu</small></span></div><button className="shop-link" onClick={()=>navigate("shop")}>Visit the Period Care Shop <Icon name="chevron" size={16}/></button></aside></div>{toast&&<div className="toast"><Check size={17}/>Cycle log saved</div>}<p className="medical-note">Concept demo — cycle predictions are simulated and are not a substitute for professional medical advice.</p></>;
}

